import type { MapStart } from '../components/map/shared.ts'
import type { Lang } from '../i18n/i18n.ts'
import data from './countries.json'

/** Generated by scripts/countries.mjs. Names come from the browser, in the visitor's language. */
export interface Country {
  /** ISO 3166-1 alpha-2, e.g. "KG". */
  readonly code: string
  readonly lat: number
  readonly lon: number
  /** International dialling prefix, e.g. "+996". Empty for the few territories without one. */
  readonly dial: string
  readonly area_km2: number
}

export const COUNTRIES: readonly Country[] = data
export const DEFAULT_COUNTRY = 'KG'

const byCode = new Map(COUNTRIES.map((country) => [country.code, country]))

export function findCountry(code: string | null | undefined): Country | undefined {
  return code ? byCode.get(code) : undefined
}

export function countryName(code: string, lang: Lang): string {
  try {
    return new Intl.DisplayNames([lang, 'en'], { type: 'region' }).of(code) ?? code
  } catch {
    return code
  }
}

/** Every country with its name in the given language, sorted by that name. */
export function listCountries(lang: Lang): { code: string; name: string }[] {
  const collator = new Intl.Collator(lang)
  return COUNTRIES.map((country) => ({ code: country.code, name: countryName(country.code, lang) })).sort((a, b) =>
    collator.compare(a.name, b.name),
  )
}

/** A first guess from the browser's language setting ("ru-KG" gives KG); the visitor confirms or changes it. */
export function guessCountry(): string {
  for (const tag of navigator.languages ?? [navigator.language]) {
    try {
      const region = new Intl.Locale(tag).region
      if (region && byCode.has(region)) return region
    } catch {
      // An odd language tag; try the next one.
    }
  }
  return DEFAULT_COUNTRY
}

/** Where the map should open for someone in this country, and how wide a view fits the country. */
export function countryView(country: Country): MapStart {
  const area = country.area_km2
  const span = area > 3_000_000 ? 'huge' : area > 500_000 ? 'large' : area > 40_000 ? 'medium' : 'small'
  return { center: { lat: country.lat, lon: country.lon }, span }
}
